import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matvec_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .u64 %rd<30>;
    .reg .u32 %r<20>;
    .reg .f32 %f<20>;
    .reg .pred %p<10>;
    .shared .align 4 .f32 sdata[256];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r3, %ctaid.x;         // row
    setp.ge.u32 %p1, %r3, %r1;
    @%p1 bra DONE;
    mov.u32 %r4, %tid.x;           // tid
    mov.u32 %r5, %ntid.x;          // blockDim.x
    cvt.u64.u32 %rd4, %r3;
    cvt.u64.u32 %rd5, %r2;
    mul.lo.u64 %rd6, %rd4, %rd5;   // row*K
    mov.f32 %f1, 0f00000000;       // sum = 0
    shl.b32 %r6, %r5, 2;           // step = ntid*4 (vectorized stride)
    div.u32 %r7, %r2, %r6;         // full_blocks = K / step
    mul.lo.u32 %r8, %r7, %r6;      // tailStart = full_blocks*step
    shl.b32 %r9, %r4, 2;           // i = tid*4
VLOOP:
    setp.ge.u32 %p2, %r9, %r8;
    @%p2 bra VLOOP_END;
    cvt.u64.u32 %rd7, %r9;
    add.u64 %rd8, %rd6, %rd7;      // index = row*K + i
    mul.lo.u64 %rd9, %rd8, 4;
    add.u64 %rd10, %rd1, %rd9;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd10];
    mul.lo.u64 %rd11, %rd7, 4;
    add.u64 %rd12, %rd2, %rd11;
    ld.global.v4.f32 {%f6, %f7, %f8, %f9}, [%rd12];
    fma.rn.f32 %f1, %f2, %f6, %f1;
    fma.rn.f32 %f1, %f3, %f7, %f1;
    fma.rn.f32 %f1, %f4, %f8, %f1;
    fma.rn.f32 %f1, %f5, %f9, %f1;
    add.u32 %r9, %r9, %r6;
    bra VLOOP;
VLOOP_END:
    add.u32 %r10, %r8, %r4;        // idx = tailStart + tid
TLOOP:
    setp.ge.u32 %p3, %r10, %r2;
    @%p3 bra TLOOP_END;
    cvt.u64.u32 %rd13, %r10;
    add.u64 %rd14, %rd6, %rd13;    // index = row*K + idx
    mul.lo.u64 %rd15, %rd14, 4;
    add.u64 %rd16, %rd1, %rd15;
    ld.global.f32 %f10, [%rd16];
    mul.lo.u64 %rd17, %rd13, 4;
    add.u64 %rd18, %rd2, %rd17;
    ld.global.f32 %f11, [%rd18];
    fma.rn.f32 %f1, %f10, %f11, %f1;
    add.u32 %r10, %r10, %r5;
    bra TLOOP;
TLOOP_END:
    // Intra-warp reduction using shfl.sync.bfly (avoids shared-memory tree reduction)
    mov.b32 %r13, %f1;
    shfl.sync.bfly.b32 %r16, %r13, 16, 0x1f, 0xffffffff;
    mov.b32 %f16, %r16;
    add.f32 %f1, %f1, %f16;
    mov.b32 %r13, %f1;
    shfl.sync.bfly.b32 %r16, %r13, 8, 0x1f, 0xffffffff;
    mov.b32 %f16, %r16;
    add.f32 %f1, %f1, %f16;
    mov.b32 %r13, %f1;
    shfl.sync.bfly.b32 %r16, %r13, 4, 0x1f, 0xffffffff;
    mov.b32 %f16, %r16;
    add.f32 %f1, %f1, %f16;
    mov.b32 %r13, %f1;
    shfl.sync.bfly.b32 %r16, %r13, 2, 0x1f, 0xffffffff;
    mov.b32 %f16, %r16;
    add.f32 %f1, %f1, %f16;
    mov.b32 %r13, %f1;
    shfl.sync.bfly.b32 %r16, %r13, 1, 0x1f, 0xffffffff;
    mov.b32 %f16, %r16;
    add.f32 %f1, %f1, %f16;
    // %f1 now holds the warp-reduced partial sum on every lane of the warp
    and.b32 %r17, %r4, 31;
    setp.ne.u32 %p4, %r17, 0;
    @%p4 bra SKIP_STORE;
    shr.u32 %r18, %r4, 5;
    mov.u64 %rd20, sdata;
    mul.wide.u32 %rd22, %r18, 4;
    add.u64 %rd21, %rd20, %rd22;
    st.shared.f32 [%rd21], %f1;
SKIP_STORE:
    bar.sync 0;
    setp.ne.u32 %p6, %r4, 0;
    @%p6 bra DONE;
    mov.u64 %rd20, sdata;
    ld.shared.f32 %f17, [%rd20+0];
    ld.shared.f32 %f18, [%rd20+4];
    add.f32 %f17, %f17, %f18;
    ld.shared.f32 %f18, [%rd20+8];
    add.f32 %f17, %f17, %f18;
    ld.shared.f32 %f18, [%rd20+12];
    add.f32 %f17, %f17, %f18;
    ld.shared.f32 %f18, [%rd20+16];
    add.f32 %f17, %f17, %f18;
    ld.shared.f32 %f18, [%rd20+20];
    add.f32 %f17, %f17, %f18;
    ld.shared.f32 %f18, [%rd20+24];
    add.f32 %f17, %f17, %f18;
    ld.shared.f32 %f18, [%rd20+28];
    add.f32 %f17, %f17, %f18;
    mul.wide.u32 %rd24, %r3, 4;
    add.u64 %rd25, %rd3, %rd24;
    st.global.f32 [%rd25], %f17;
DONE:
    ret;
